    "diagramHtml": "\n<div class=\"diagram-wrapper\">\n  <div class=\"diagram-header\">\n    <div class=\"diagram-badge\">BATCH 02 VISUAL GUIDE — POLE 1</div>\n    <h4>The aissistant: four separable layers and a real lifecycle machine</h4>\n    <p>Body, soul, identity and permissions are independent — so each can be upgraded or swapped without touching the others</p>\n  </div>\n  <div class=\"diagram-svg-container\">\n    <svg viewBox=\"0 0 920 340\" width=\"100%\" height=\"auto\" xmlns=\"http://www.w3.org/2000/svg\">\n\n      <defs>\n        <marker id=\"arr-02\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n          <path d=\"M 0 1 L 8 5 L 0 9 z\" fill=\"var(--diagram-accent, #7c3aed)\"/>\n        </marker>\n        <marker id=\"arrg-02\" viewBox=\"0 0 10 10\" refX=\"6\" refY=\"5\" markerWidth=\"6\" markerHeight=\"6\" orient=\"auto-start-reverse\">\n          <path d=\"M 0 1 L 8 5 L 0 9 z\" fill=\"#10b981\"/>\n        </marker>\n      </defs>\n      <g transform=\"translate(20, 20)\">\n        <rect width=\"210\" height=\"150\" rx=\"8\" fill=\"var(--surface-card, #ffffff)\" stroke=\"var(--border-color, #e2e8f0)\" stroke-width=\"1.2\"/>\n        <text x=\"12\" y=\"26\" font-family=\"system-ui, sans-serif\" font-size=\"12.5\" font-weight=\"700\" fill=\"var(--text-primary, #0f172a)\">1 · BODY (ADAPTER)</text>\n        <text x=\"12\" y=\"44\" font-family=\"system-ui, sans-serif\" font-size=\"10.5\" fill=\"var(--text-secondary, #475569)\">How the agent is called</text>\n        <text x=\"12\" y=\"61\" font-family=\"system-ui, sans-serif\" font-size=\"10.5\" fill=\"var(--text-secondary, #475569)\">native · cli · container</text>\n        <text x=\"12\" y=\"78\" font-family=\"system-ui, sans-serif\" font-size=\"10.5\" fill=\"var(--text-secondary, #475569)\">Swappable per agent</text>\n        <text x=\"12\" y=\"95\" font-family=\"system-ui, sans-serif\" font-size=\"10.5\" fill=\"#6d28d9\">= the runtime stance</text>\n      </g>\n      <g transform=\"translate(245, 20)\">\n        <rect width=\"210\" height=\"150\" rx=\"8\" fill=\"var(--surface-card, #ffffff)\" stroke=\"var(--border-color, #e2e8f0)\" stroke-width=\"1.2\"/>\n        <text x=\"12\" y=\"26\" font-family=\"system-ui, sans-serif\" font-size=\"12.5\" font-weight=\"700\" fill=\"var(--text-primary, #0f172a)\">2 · SOUL (FILES)</text>\n        <text x=\"12\" y=\"44\" font-family=\"system-ui, sans-serif\" font-size=\"10.5\" fill=\"var(--text-secondary, #475569)\">AGENTS.md + notes</text>\n        <text x=\"12\" y=\"61\" font-family=\"system-ui, sans-serif\" font-size=\"10.5\" fill=\"var(--text-secondary, #475569)\">Persistent across runs</text>\n        <text x=\"12\" y=\"78\" font-family=\"system-ui, sans-serif\" font-size=\"10.5\" fill=\"var(--text-secondary, #475569)\">Plain files, git-friendly</text>\n        <text x=\"12\" y=\"95\" font-family=\"system-ui, sans-serif\" font-size=\"10.5\" fill=\"#059669\">Not a DB blob</text>\n      </g>\n      <g transform=\"translate(470, 20)\">\n        <rect width=\"210\" height=\"150\" rx=\"8\" fill=\"var(--surface-card, #ffffff)\" stroke=\"var(--border-color, #e2e8f0)\" stroke-width=\"1.2\"/>\n        <text x=\"12\" y=\"26\" font-family=\"system-ui, sans-serif\" font-size=\"12.5\" font-weight=\"700\" fill=\"var(--text-primary, #0f172a)\">3 · IDENTITY</text>\n        <text x=\"12\" y=\"44\" font-family=\"system-ui, sans-serif\" font-size=\"10.5\" fill=\"var(--text-secondary, #475569)\">Ed25519 keypair</text>\n        <text x=\"12\" y=\"61\" font-family=\"system-ui, sans-serif\" font-size=\"10.5\" fill=\"var(--text-secondary, #475569)\">Generated per agent</text>\n        <text x=\"12\" y=\"78\" font-family=\"system-ui, sans-serif\" font-size=\"10.5\" fill=\"var(--text-secondary, #475569)\">agent_seal proof</text>\n        <text x=\"12\" y=\"95\" font-family=\"system-ui, sans-serif\" font-size=\"10.5\" fill=\"#1d4ed8\">routes/agents.ts</text>\n      </g>\n      <g transform=\"translate(695, 20)\">\n        <rect width=\"205\" height=\"150\" rx=\"8\" fill=\"var(--surface-card, #ffffff)\" stroke=\"var(--border-color, #e2e8f0)\" stroke-width=\"1.2\"/>\n        <text x=\"12\" y=\"26\" font-family=\"system-ui, sans-serif\" font-size=\"12.5\" font-weight=\"700\" fill=\"var(--text-primary, #0f172a)\">4 · PERMISSIONS</text>\n        <text x=\"12\" y=\"44\" font-family=\"system-ui, sans-serif\" font-size=\"10.5\" fill=\"var(--text-secondary, #475569)\">Explicit allow-list</text>\n        <text x=\"12\" y=\"61\" font-family=\"system-ui, sans-serif\" font-size=\"10.5\" fill=\"var(--text-secondary, #475569)\">Sandbox escape NEVER default</text>\n        <text x=\"12\" y=\"78\" font-family=\"system-ui, sans-serif\" font-size=\"10.5\" fill=\"var(--text-secondary, #475569)\">Revocation is permanent</text>\n        <text x=\"12\" y=\"95\" font-family=\"system-ui, sans-serif\" font-size=\"10.5\" fill=\"#b45309\">fail-closed</text>\n      </g>\n\n      <rect x=\"20\" y=\"190\" width=\"880\" height=\"130\" rx=\"10\" fill=\"var(--surface-card, #ffffff)\" stroke=\"#7c3aed\" stroke-width=\"1.6\"/>\n      <text x=\"40\" y=\"218\" font-family=\"system-ui, sans-serif\" font-size=\"13\" font-weight=\"700\" fill=\"#6d28d9\">THE AGENT-LIFECYCLE STATE MACHINE (not a boolean)</text>\n      <g font-family=\"system-ui, sans-serif\" font-size=\"11\" font-weight=\"600\">\n        <rect x=\"40\" y=\"236\" width=\"118\" height=\"30\" rx=\"15\" fill=\"#f59e0b\" fill-opacity=\"0.16\" stroke=\"#f59e0b\"/>\n        <text x=\"58\" y=\"256\" fill=\"#b45309\">pending_approval</text>\n        <rect x=\"188\" y=\"236\" width=\"96\" height=\"30\" rx=\"15\" fill=\"#3b82f6\" fill-opacity=\"0.14\" stroke=\"#3b82f6\"/>\n        <text x=\"214\" y=\"256\" fill=\"#1d4ed8\">preparing</text>\n        <rect x=\"314\" y=\"236\" width=\"92\" height=\"30\" rx=\"15\" fill=\"#3b82f6\" fill-opacity=\"0.14\" stroke=\"#3b82f6\"/>\n        <text x=\"338\" y=\"256\" fill=\"#1d4ed8\">verifying</text>\n        <rect x=\"436\" y=\"236\" width=\"86\" height=\"30\" rx=\"15\" fill=\"#10b981\" fill-opacity=\"0.16\" stroke=\"#10b981\"/>\n        <text x=\"466\" y=\"256\" fill=\"#059669\">ready</text>\n        <rect x=\"552\" y=\"236\" width=\"104\" height=\"30\" rx=\"15\" fill=\"#8b5cf6\" fill-opacity=\"0.14\" stroke=\"#8b5cf6\"/>\n        <text x=\"574\" y=\"256\" fill=\"#6d28d9\">pause/resume</text>\n        <rect x=\"686\" y=\"236\" width=\"96\" height=\"30\" rx=\"15\" fill=\"#ef4444\" fill-opacity=\"0.14\" stroke=\"#ef4444\"/>\n        <text x=\"714\" y=\"256\" fill=\"#b91c1c\">terminate</text>\n      </g>\n      <text x=\"40\" y=\"298\" font-family=\"system-ui, sans-serif\" font-size=\"11\" fill=\"var(--text-secondary, #475569)\">A hire must pass an eval gate before it ever reaches \"ready\" — the same discipline we want for a provisioned Hermes home.</text>\n    </svg>\n  </div>\n</div>",
